      // Rastrear ADD TO CART (que também registra a conversão da página de vendas)
      console.log('🛒 DEBUGGING: Iniciando trackAddToCart...');
      await trackAddToCart();
      console.log('✅ ADD TO CART registrado com sucesso');

      // 2. Abrir popup
      setIsPopupOpen(true);

